import pathlib,html
root=pathlib.Path(__file__).resolve().parents[1]
emails=[('welcome','Welcome to your everyday.','A first look at the fictional KOVA collection.','WELCOME / DRAFT 01','A quieter starting point.',['Thanks for taking a first look at KOVA. Our fictional collection begins with two fit ideas, Everyday and Oversized, in Ink, Chalk and Sage.','The idea is simple: give your everyday wardrobe a useful starting point, then let the rest of the outfit be yours.','Explore the preview to compare the concept fits and colours. The demo does not take orders or store email addresses.'],'Explore the first drop','Proposed welcome flow only, after an explicit signup in a future consented system. No subscription or automated send exists here.'),('preview','Meet your everyday starting point.','Everyday or Oversized? Start with the fit.','PREVIEW / DRAFT 02','Two fits. Three colours.',['Some days call for a familiar straight shape. Some call for a little more room. KOVA’s proposed Everyday and Oversized tees give those ideas a place to start.','The concept prices are ₹699 for Everyday and ₹899 for Oversized. Ink, Chalk and Sage make up the proposed palette. These are fictional prices, not items available to purchase.','Before any real launch, we would publish measured size charts, verified fabric details, delivery costs and return terms. For now, explore the idea.'],'Compare the concept fits','Proposed prelaunch email to an explicitly opted-in list. No list has been collected.'),('launch','The first drop, in preview.','Explore KOVA’s fictional launch page.','LAUNCH / DRAFT 03','Wear your everyday.',['The first-drop preview is ready to explore: two fits, three colours and a little less outfit overthinking.','Choose a concept fit and colour, read the fit guide and try the demo signup. It does not save your email, send a message or create an order.','This email demonstrates a launch message for the portfolio. A real launch version would only be sent after product information, inventory, payment and delivery checks were complete.'],'Explore the launch preview','Launch draft only. Availability and product-quality claims must be verified before a real send.'),('cart','Still deciding on your tee?','Check the fit and total price before returning to your basket.','FUTURE STORE / DRAFT 04','Take another look.',['Still thinking about the tee you viewed? Before deciding, compare the garment measurements with a tee you own and check the full price, delivery costs and return terms.','In a future working store, this message would link a consented shopper back to their saved basket. No basket, tracking email or checkout exists in this prototype.','For this demonstration, the button opens the collection preview. No discount, stock shortage or time limit is invented.'],'Review the collection preview','Future cart flow only, subject to appropriate consent, a real saved basket and suppression after purchase. The button is a preview substitute, not a cart-recovery link.')]
for slug,subject,preheader,kicker,heading,paras,cta,conditions in emails:
 body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(subject)} — KOVA email draft</title><style>body{{margin:0;background:#e9ebdf;color:#272e28;font:15px/1.85 Arial,sans-serif}}.wrap{{max-width:640px;margin:40px auto;background:#f5f2ea}}.draft{{padding:20px 35px;background:#272e28;color:#d6dfc9;font-size:11px}}.draft b{{color:#fff}}header{{padding:40px 35px;border-bottom:1px solid #d8dbcf;letter-spacing:7px;font-size:31px}}main{{padding:35px}}small{{font-size:10px;letter-spacing:1.5px;color:#7c896e}}h1{{font:normal 47px/1.1 Georgia,serif;letter-spacing:-1px;margin:25px 0}}p{{color:#707963;margin:23px 0}}.cta{{display:inline-block;padding:14px 22px;background:#272e28;color:#f5f2ea;text-decoration:none;font-size:12px;margin:15px 0}}footer{{padding:25px 35px;border-top:1px solid #d8dbcf;font-size:10px;color:#859177}}.conditions{{font-size:11px;border-left:2px solid #b1bea0;padding-left:15px}}.back{{display:block;font-size:11px;margin-top:20px;color:#637653}}@media(max-width:600px){{.wrap{{margin:0}}main,header{{padding:28px}}h1{{font-size:40px}}.draft{{padding:18px 28px}}}}</style></head><body><div class="wrap"><div class="draft"><b>SUBJECT:</b> {html.escape(subject)}<br><b>PREHEADER:</b> {html.escape(preheader)}<br>UNSENT EMAIL DRAFT / FICTIONAL PORTFOLIO</div><header>KOVA <span style="font-size:9px;letter-spacing:3px">LIFESTYLE</span></header><main><small>{kicker}</small><h1>{heading}</h1>{''.join('<p>'+html.escape(p)+'</p>' for p in paras)}<a class="cta" href="../drop.html?utm_source=email&amp;utm_medium=email&amp;utm_campaign=wear_your_everyday&amp;utm_content={slug}">{cta} ↗</a><p class="conditions">{conditions}</p></main><footer>AI-assisted copy for a fictional brand. No emails have been sent.<br>A real send requires approved sender details, consent handling and a working unsubscribe route.<br>No sender address or unsubscribe link is invented in this draft.<a class="back" href="../index.html#seo">Back to the marketing portfolio ↗</a></footer></div></body></html>'''
 (root/'dist'/'emails'/f'{slug}.html').write_text(body)
